*{box-sizing:border-box} :root{--ink:#f4f3e8;--muted:#a9aca1;--lime:#d8f36a;--dark:#101513;--glass:rgba(17,23,21,.78);--line:rgba(242,243,226,.13)}html,body{height:100%;margin:0;overflow:hidden;background:#d7e1d0;color:var(--ink);font-family:Manrope,system-ui,sans-serif;touch-action:none}button{font:inherit;color:inherit;border:0;cursor:pointer}#game{position:relative;width:100%;height:100%;height:100dvh;overflow:hidden;background:#cddacf}#world{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(9,16,16,.47),transparent 20%,transparent 55%,rgba(9,15,14,.32) 100%),linear-gradient(90deg,rgba(8,14,13,.18),transparent 35%,transparent 75%,rgba(8,14,13,.08))}.topbar{position:absolute;z-index:2;top:max(22px,env(safe-area-inset-top));left:4.2%;right:4.2%;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:12px}.brand-mark,.loader-mark{width:42px;height:42px;border:1px solid rgba(216,243,106,.66);border-radius:13px;display:grid;place-items:center;position:relative;font-size:16px;font-weight:800;letter-spacing:-1px;color:var(--lime);background:rgba(16,21,19,.54);backdrop-filter:blur(12px)}.brand-mark span,.loader-mark span{position:absolute;right:4px;top:3px;font-size:9px;color:#f5f2dd}.brand-name{font-size:13px;letter-spacing:1.55px;font-weight:500;line-height:1.2}.brand-name b{font-weight:800}.brand-sub{font-family:'DM Mono',monospace;font-size:8px;letter-spacing:1.15px;color:#d0d5c7;margin-top:5px}.top-actions{display:flex;align-items:center;gap:10px}.wallet{height:38px;border:1px solid var(--line);border-radius:10px;display:flex;align-items:center;padding:0 12px;gap:7px;background:var(--glass);backdrop-filter:blur(12px);font-family:'DM Mono',monospace;font-size:12px}.wallet .coin{color:var(--lime);font-size:11px}.wallet small{font-size:9px;color:var(--muted)}.icon-btn{width:38px;height:38px;border-radius:10px;border:1px solid var(--line);background:var(--glass);backdrop-filter:blur(12px);font-size:17px}.location-card{position:absolute;z-index:2;top:105px;left:4.2%;display:flex;align-items:center;gap:11px;padding:11px 14px;border:1px solid var(--line);border-radius:10px;background:var(--glass);backdrop-filter:blur(10px)}.live-dot{width:7px;height:7px;background:var(--lime);border-radius:50%;box-shadow:0 0 9px var(--lime)}.location-card div:not(.weather){display:flex;flex-direction:column;gap:3px}.location-card small,.vehicle-nameplate small,.mission-chip small{font-family:'DM Mono',monospace;font-size:8px;letter-spacing:1.1px;color:#aab1a4}.location-card strong{font-size:10px;letter-spacing:1.2px}.loc-sep{height:24px;width:1px;background:var(--line);margin:0 1px 0 5px}.weather{font-size:15px;color:#f2d879}.weather span{font-size:10px;font-family:'DM Mono',monospace;color:#e4e6d9;margin-left:3px}.mission-chip{position:absolute;top:108px;right:4.2%;z-index:2;display:flex;align-items:center;gap:10px;padding:9px 13px;border:1px solid var(--line);border-radius:10px;background:var(--glass);backdrop-filter:blur(10px)}.mission-icon{width:28px;height:28px;border-radius:8px;background:rgba(216,243,106,.12);display:grid;place-items:center;color:var(--lime);font-size:18px}.mission-chip div{display:flex;flex-direction:column;gap:2px}.mission-chip strong{font-size:11px}.mission-arrow{font-size:20px;color:#8f988b;margin-left:5px}.vehicle-hud{position:absolute;z-index:2;bottom:140px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:20px;padding:12px 19px;border-radius:13px;border:1px solid rgba(255,255,255,.16);background:rgba(15,21,19,.78);backdrop-filter:blur(14px);min-width:320px}.speed-block{min-width:130px}.speed-label,.gear-block small,.ride-stat small{font:8px 'DM Mono',monospace;letter-spacing:1.4px;color:#adb4a7}.speed-row{display:flex;align-items:baseline;gap:6px;margin:0 0 5px}.speed-row strong{font:500 32px 'DM Mono',monospace;letter-spacing:-2px;line-height:1}.speed-unit{font:9px 'DM Mono',monospace;color:#bbc1b3}.speed-track{width:124px;height:2px;background:#3c453d}.speed-track i{height:100%;width:0;display:block;background:var(--lime);box-shadow:0 0 7px var(--lime);transition:width .1s}.hud-divider{width:1px;height:44px;background:var(--line)}.gear-block{width:45px;display:grid;grid-template-columns:1fr;justify-items:center;gap:2px}.gear-block>strong{font:500 22px 'DM Mono',monospace;color:var(--lime)}.rpm{width:40px;height:2px;background:#374038;display:block}.rpm i{display:block;width:25%;height:100%;background:#e5ad61}.rpm-label{font-size:7px!important;letter-spacing:.5px!important}.rpm-label b{color:#e6e9dc;font-weight:400}.ride-stat{min-width:85px;display:flex;flex-direction:column;gap:7px}.ride-stat strong{font:13px 'DM Mono',monospace}.ride-stat em{font-size:9px;color:#aeb5a8;font-style:normal}.quick-menu{position:absolute;z-index:2;left:50%;transform:translateX(-50%);bottom:31px;display:flex;gap:8px}.quick-menu button{height:39px;padding:0 13px;border:1px solid var(--line);border-radius:9px;background:var(--glass);backdrop-filter:blur(12px);font:8px 'DM Mono',monospace;letter-spacing:.6px;white-space:nowrap;display:flex;align-items:center;gap:8px}.quick-menu button span{font-size:14px;color:var(--lime)}.quick-menu button:hover{border-color:rgba(216,243,106,.6)}.control-hint{position:absolute;bottom:92px;left:50%;transform:translateX(-50%);font:8px 'DM Mono',monospace;letter-spacing:.6px;color:#e2e4da;text-shadow:0 1px 6px #101513;white-space:nowrap}.control-hint span{padding:3px 5px;border:1px solid rgba(255,255,255,.3);border-radius:4px;background:rgba(12,16,14,.35);font-size:7px}.control-hint i{font-style:normal;padding:0 5px;color:var(--lime)}.controls{position:absolute;inset:0;z-index:1;pointer-events:none}.steer-group,.action-group{position:absolute;bottom:120px;pointer-events:auto;display:flex;align-items:flex-end;gap:8px}.steer-group{left:4.2%}.action-group{right:4.2%;gap:7px}.control-btn{pointer-events:auto;user-select:none;-webkit-user-select:none;touch-action:none;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;background:rgba(17,23,21,.74);border:1px solid rgba(255,255,255,.22);backdrop-filter:blur(9px);box-shadow:0 6px 20px rgba(0,0,0,.12);transition:transform .1s,background .1s}.control-btn:active,.control-btn.active{transform:scale(.95);background:rgba(216,243,106,.24);border-color:var(--lime)}.control-btn span{font:7px 'DM Mono',monospace;letter-spacing:.65px;color:#d7dccf}.control-btn b{font:15px 'DM Mono',monospace;color:#fff}.steer{width:49px;height:54px;border-radius:12px;font:30px Manrope,sans-serif;color:var(--lime)}.small-action{width:52px;height:47px;border-radius:10px}.small-action b{font-size:11px;color:var(--lime)}.shift-btn{width:42px;height:50px;border-radius:10px}.shift-btn b{font-size:19px;color:var(--lime)}.brake,.accelerate{width:59px;height:62px;border-radius:13px}.brake b{font-size:13px;color:#f28772}.accelerate{background:rgba(216,243,106,.16);border-color:rgba(216,243,106,.54)}.accelerate b{font-size:16px;color:var(--lime)}.vehicle-nameplate{position:absolute;z-index:2;left:4.2%;bottom:31px;display:flex;align-items:center;gap:10px}.vehicle-icon{width:32px;height:32px;border-radius:9px;display:grid;place-items:center;background:rgba(216,243,106,.15);color:var(--lime);font-size:17px}.vehicle-nameplate div{display:flex;flex-direction:column;gap:3px}.vehicle-nameplate strong{font-size:10px;letter-spacing:.8px}.vehicle-condition{font:7px 'DM Mono',monospace;color:var(--lime);padding:4px 6px;border:1px solid rgba(216,243,106,.32);border-radius:5px;margin-left:4px}.toast{position:absolute;z-index:10;left:50%;top:20%;transform:translate(-50%,-10px);opacity:0;pointer-events:none;padding:11px 16px;border:1px solid rgba(216,243,106,.4);border-radius:9px;background:rgba(13,19,17,.92);font-size:11px;transition:.3s}.toast.show{opacity:1;transform:translate(-50%,0)}.overlay,.paused{position:absolute;z-index:8;inset:0;background:rgba(5,9,8,.6);backdrop-filter:blur(8px);display:flex;align-items:center;justify-content:center;padding:20px}.hidden{display:none!important}.panel{position:relative;width:min(760px,94vw);max-height:min(690px,90vh);overflow:auto;border:1px solid rgba(255,255,255,.16);border-radius:18px;padding:30px;background:linear-gradient(145deg,rgba(28,36,31,.98),rgba(14,19,17,.98));box-shadow:0 24px 80px rgba(0,0,0,.4)}.close-btn{position:absolute;right:20px;top:18px;width:32px;height:32px;border:1px solid var(--line);border-radius:9px;background:rgba(255,255,255,.04);font-size:21px;color:#c5cabb}.panel-eyebrow{font:9px 'DM Mono',monospace;letter-spacing:1.8px;color:var(--lime)}.panel h1{font-size:30px;letter-spacing:-1.3px;margin:8px 0 4px}.panel-desc{font-size:12px;color:#afb5a9;margin:0 0 22px}.panel-content{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px}.vehicle-card,.upgrade-card{border:1px solid var(--line);border-radius:12px;padding:15px;background:rgba(255,255,255,.035);min-height:110px;display:flex;flex-direction:column;justify-content:space-between}.card-top{display:flex;align-items:flex-start;justify-content:space-between}.card-icon{font-size:23px;color:var(--lime)}.card-type{font:8px 'DM Mono',monospace;letter-spacing:1px;color:#929b8e}.vehicle-card h3,.upgrade-card h3{margin:8px 0 3px;font-size:14px}.vehicle-card p,.upgrade-card p{margin:0;color:#aab1a4;font-size:10px}.card-footer{display:flex;align-items:center;justify-content:space-between;margin-top:14px}.card-price{font:11px 'DM Mono',monospace;color:var(--lime)}.card-button{border:1px solid rgba(216,243,106,.42);background:rgba(216,243,106,.12);border-radius:7px;padding:7px 10px;color:var(--lime);font:8px 'DM Mono',monospace;letter-spacing:.7px}.card-button:disabled{opacity:.45;cursor:default}.tuning-tools{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:12px}.tuning-tools button{border:1px solid var(--line);border-radius:7px;background:rgba(255,255,255,.04);padding:7px 10px;font:8px 'DM Mono',monospace;color:#b9c0b3}.tuning-tools button.selected{border-color:var(--lime);color:var(--lime)}.color-input{width:36px;height:26px;padding:0;border:0;background:transparent}.paused .pause-card{text-align:center;width:min(340px,90vw);border:1px solid var(--line);border-radius:16px;padding:34px;background:rgba(18,25,22,.95)}.pause-mark{font-size:24px;color:var(--lime)}.pause-card h2{margin:12px 0 5px;font-size:25px}.pause-card p{font-size:12px;color:#aab1a4;margin:0 0 22px}.pause-card button{height:42px;padding:0 16px;border-radius:8px;background:var(--lime);color:#182014;font:800 9px 'DM Mono',monospace;letter-spacing:1px}.pause-card button b{font-size:15px;margin-left:12px}.loading{position:absolute;inset:0;z-index:20;background:#111713;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;transition:opacity .7s}.loading.done{opacity:0;pointer-events:none}.loader-mark{width:58px;height:58px;font-size:22px;border-radius:17px}.loader-line{width:150px;height:2px;background:#30382f;overflow:hidden}.loader-line i{display:block;height:100%;width:40%;background:var(--lime);animation:load 1s ease-in-out infinite alternate}.loading small{font:8px 'DM Mono',monospace;letter-spacing:2px;color:#929a8f}@keyframes load{from{transform:translateX(-20%)}to{transform:translateX(170%)}}body.night .vignette{background:linear-gradient(180deg,rgba(8,12,24,.58),transparent 20%,transparent 53%,rgba(4,8,17,.46) 100%),linear-gradient(90deg,rgba(6,10,19,.18),transparent 36%,transparent 75%,rgba(4,7,17,.12))}
@media(max-width:760px){.topbar{left:16px;right:16px;top:max(14px,env(safe-area-inset-top))}.brand-mark{width:36px;height:36px;border-radius:11px}.brand{gap:9px}.brand-name{font-size:11px;letter-spacing:1px}.brand-sub{font-size:7px;letter-spacing:.8px}.top-actions{gap:6px}.wallet{height:34px;padding:0 8px;gap:5px;font-size:10px}.icon-btn{width:34px;height:34px}.location-card{top:68px;left:16px;padding:8px 10px;gap:8px}.mission-chip{top:68px;right:16px;padding:7px 9px;gap:7px}.mission-icon{width:24px;height:24px}.mission-chip strong{font-size:9px}.mission-chip small{font-size:7px}.mission-arrow{margin-left:0}.vehicle-hud{bottom:calc(118px + env(safe-area-inset-bottom));min-width:0;width:216px;gap:12px;padding:9px 12px}.speed-block{min-width:105px}.speed-row strong{font-size:27px}.speed-track{width:100px}.gear-block{width:38px}.hud-hide{display:none}.steer-group{left:16px;bottom:calc(22px + env(safe-area-inset-bottom));gap:7px}.action-group{right:16px;bottom:calc(22px + env(safe-area-inset-bottom));gap:5px}.steer{width:47px;height:52px}.small-action{width:39px;height:41px}.small-action span{font-size:6px}.small-action b{font-size:9px}.shift-btn{width:35px;height:44px}.shift-btn span{font-size:6px}.shift-btn b{font-size:15px}.brake,.accelerate{width:49px;height:53px}.brake span,.accelerate span{font-size:6px}.control-hint{display:none}.quick-menu{bottom:calc(87px + env(safe-area-inset-bottom));gap:5px}.quick-menu button{height:34px;padding:0 9px;font-size:7px;gap:5px}.quick-menu button span{font-size:12px}.vehicle-nameplate{display:none}.panel{padding:24px 18px;max-height:88vh}.panel h1{font-size:26px}.panel-desc{font-size:11px}.panel-content{gap:8px}.vehicle-card,.upgrade-card{padding:11px;min-height:112px}.vehicle-card h3,.upgrade-card h3{font-size:12px}.card-button{padding:7px 8px;font-size:7px}.card-price{font-size:9px}.location-card strong{font-size:9px}}
@media(max-width:390px){.action-group{right:10px;gap:4px}.steer-group{left:10px;gap:5px}.small-action{width:35px}.shift-btn{width:31px}.brake,.accelerate{width:45px}.quick-menu button{padding:0 7px;letter-spacing:0}.weather{display:none}.loc-sep{display:none}}

import * as THREE from 'three';

const $ = (s) => document.querySelector(s);
const canvas = $('#world');
const scene = new THREE.Scene();
const daySky = new THREE.Color('#a9c5c6');
scene.background = daySky;
scene.fog = new THREE.Fog(daySky, 70, 235);
const camera = new THREE.PerspectiveCamera(54, innerWidth / innerHeight, .1, 420);
const renderer = new THREE.WebGLRenderer({ canvas, antialias: false, powerPreference: 'low-power' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.5));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = false;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;
const hemi = new THREE.HemisphereLight('#e5f3ed', '#55564b', 2.15); scene.add(hemi);
const sun = new THREE.DirectionalLight('#fff0ce', 2.15); sun.position.set(-45, 80, 30); scene.add(sun);
const mat = (color, roughness=.85, metalness=0) => new THREE.MeshStandardMaterial({ color, roughness, metalness });
const M = {
  asphalt: mat('#353d3c'), sidewalk: mat('#bdb9aa'), sand: mat('#d0c3a6'), white: mat('#eee9d9'), trim: mat('#e9e3d3'),
  cream: mat('#dfcba9'), ochre: mat('#c8a47a'), pale: mat('#d8d1bc'), blue: mat('#6b98a1'), red: mat('#c66b51'), green: mat('#708366'), dark: mat('#27302d'),
  glass: new THREE.MeshStandardMaterial({ color:'#83a6a6', metalness:.16, roughness:.28 }), window: mat('#627979',.36), roadLine: mat('#dbd1a3'), lamp: new THREE.MeshBasicMaterial({color:'#ffd787'}),
  tire: mat('#171a19'), metal: mat('#9aa09a',.32,.72), black: mat('#141918',.45),
};
const boxGeo = new THREE.BoxGeometry(1,1,1), cylGeo = new THREE.CylinderGeometry(1,1,1,12), sphereGeo = new THREE.SphereGeometry(1,12,8);
function addBox(parent, x,y,z, sx,sy,sz, material, rotY=0){const o=new THREE.Mesh(boxGeo,material);o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.rotation.y=rotY;parent.add(o);return o;}
function addCylinder(parent,x,y,z,r,h,material,rx=0,rz=0){const o=new THREE.Mesh(cylGeo,material);o.position.set(x,y,z);o.scale.set(r,h,r);o.rotation.set(rx,0,rz);parent.add(o);return o;}
function addSphere(parent,x,y,z,sx,sy,sz,material){const o=new THREE.Mesh(sphereGeo,material);o.position.set(x,y,z);o.scale.set(sx,sy,sz);parent.add(o);return o;}

// A compact, low-poly medina with broad boulevards and tight side streets.
const city = new THREE.Group(); scene.add(city);
addBox(city,0,-.55,0,500,1,500,M.sand);
const roadMat = M.asphalt;
for(let v=-240;v<=240;v+=48){
  addBox(city,0,-.035,v,500,.13,11.5,roadMat); addBox(city,v,-.035,0,11.5,.13,500,roadMat);
  for(let p=-225;p<=225;p+=10){
    addBox(city,p,.035,v,4,.015,.11,M.roadLine); addBox(city,v,.035,p,.11,.015,4,M.roadLine);
  }
  for(const sign of [-1,1]){
    const offset=sign*7.7;
    addBox(city,0,.03,v+offset,500,.17,3.8,M.sidewalk); addBox(city,v+offset,.03,0,3.8,.17,500,M.sidewalk);
  }
}
// Block plots with warm plaster, blue doors, striped awnings, roof details and tiny shop signs.
const facadeMats=[M.cream,M.ochre,M.pale,M.blue,M.red,M.green];
let seed=12451; const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};
function building(x,z,w,d,h,variant){
  const g=new THREE.Group(); city.add(g); const wall=facadeMats[variant%facadeMats.length];
  addBox(g,x,h/2,z,w,h,d,wall);
  addBox(g,x,h+.13,z,w+.22,.26,d+.22,M.trim);
  addBox(g,x,h*.53,z+d/2+.025,w*.88,.12,.08,M.trim);
  const floors=Math.max(1,Math.floor(h/3.2)); const columns=Math.max(1,Math.floor(w/3.4));
  for(let floor=0;floor<floors;floor++) for(let c=0;c<columns;c++){
    const wx=x-w/2+(c+.5)*w/columns, wy=1.15+floor*3.1;
    if(wy>h-.8) continue;
    addBox(g,wx,wy,z+d/2+.055,1.05,1.45,.09, M.window);
    addBox(g,wx,wy,z+d/2+.105,1.28,1.7,.07, M.trim);
    addBox(g,wx,wy+1.08,z+d/2+.15,1.34,.10,.12, M.blue);
  }
  // ground floor storefront and colorful retractable canopy
  const shop = variant%3===0;
  if(shop){
    addBox(g,x,1.05,z+d/2+.10,2.4,2.15,.12,M.blue);
    addBox(g,x,2.32,z+d/2+.20,3.5,.42,.45,variant%2?M.red:M.green);
    addBox(g,x,2.34,z+d/2+.44,3.1,.08,.04,M.white);
    for(let stripe=-1;stripe<=1;stripe++) addBox(g,x+stripe*.92,2.05,z+d/2+.43,.5,.5,.05, stripe%2?M.white:M.cream);
  }
  // roof parapet, water tank and occasional satellite dish
  addBox(g,x,h+.35,z+d/2,w+.35,.62,.22,M.trim);
  addBox(g,x,h+.35,z-d/2,w+.35,.62,.22,M.trim);
  if(rand()>.56){addCylinder(g,x+(rand()-.5)*w,h+.75,z+(rand()-.5)*d,.48,.9,M.dark);}
  if(rand()>.75){addCylinder(g,x+w*.25,h+.6,z,.43,.09,M.metal,Math.PI/2);}
}
for(let bx=-4;bx<=4;bx++) for(let bz=-4;bz<=4;bz++){
  const cx=bx*48, cz=bz*48;
  if(Math.abs(cx)<30&&Math.abs(cz)<30) continue;
  const style=Math.floor(rand()*6), count=1+(rand()>.42?1:0);
  for(let i=0;i<count;i++){
    const side= i===0 ? -1:1, px=cx+side*(4+rand()*5), pz=cz+(rand()-.5)*19;
    building(px,pz,7+rand()*5,8+rand()*5,6+rand()*8,style+i);
  }
}
// Medinan minaret landmark.
const minaret=new THREE.Group();city.add(minaret);minaret.position.set(-20,0,-24);
addBox(minaret,0,5,0,5,10,5,M.cream);addBox(minaret,0,10.5,0,5.8,1,5.8,M.trim);addBox(minaret,0,14,0,3.5,6,3.5,M.ochre);addBox(minaret,0,17.1,0,4,.35,4,M.white);addCylinder(minaret,0,19,0,.15,3,M.metal);
for(let y=2;y<9;y+=3) addBox(minaret,0,y,2.55,.9,1.5,.08,M.window);
// Date palms, street lamps, signal heads and parked compact cars on street corners.
const props=new THREE.Group();city.add(props);
function palm(x,z){addCylinder(props,x,2.3,z,.22,4.6,M.ochre);for(let i=0;i<6;i++){const a=i*Math.PI/3;const leaf=addBox(props,x+Math.sin(a)*1.1,4.65,z+Math.cos(a)*1.1,2.3,.13,.36,M.green,a);leaf.rotation.z=Math.cos(a)*-.3;}}
function streetlamp(x,z){addCylinder(props,x,3,z,.07,6,M.dark);addBox(props,x+.75,5.8,z,1.5,.08,.08,M.dark);addSphere(props,x+1.4,5.75,z,.16,.12,.16,M.lamp);}
for(let p=-190;p<=190;p+=48){for(const s of [-1,1]){palm(p+s*9, s*9);streetlamp(p+s*9,s*7);}}
function signal(x,z,rot=0){const g=new THREE.Group();g.position.set(x,0,z);g.rotation.y=rot;props.add(g);addCylinder(g,0,2.4,0,.08,4.8,M.dark);addBox(g,0,4.5,.5,.5,1.1,.4,M.black);for(let y=4.8;y>4;y-=.32)addSphere(g,0,y,.72,.105,.105,.06,M.red);}
for(const v of [-48,0,48]){signal(v+7,7,0);signal(-7,v+7,Math.PI/2);}
for(let i=0;i<18;i++){
