const boxGeo=new THREE.BoxGeometry(1,1,1),cylGeo=new THREE.CylinderGeometry(1,1,1,12),sphereGeo=new THREE.SphereGeometry(1,12,8);
function addBox(parent,x,y,z,sx,sy,sz,material,rotY=0){const o=new THREE.Mesh(boxGeo,material);o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.rotation.y=rotY;parent.add(o);return o;}
function addCylinder(parent,x,y,z,r,h,material,rx=0,rz=0){const o=new THREE.Mesh(cylGeo,material);o.position.set(x,y,z);o.scale.set(r,h,r);o.rotation.set(rx,0,rz);parent.add(o);return o;}
function addSphere(parent,x,y,z,sx,sy,sz,material){const o=new THREE.Mesh(sphereGeo,material);o.position.set(x,y,z);o.scale.set(sx,sy,sz);parent.add(o);return o;}
const city=new THREE.Group();scene.add(city);addBox(city,0,-.55,0,500,1,500,M.sand);
for(let v=-240;v<=240;v+=48){addBox(city,0,-.035,v,500,.13,11.5,M.asphalt);addBox(city,v,-.035,0,11.5,.13,500,M.asphalt);addBox(city,0,.03,v+7.7,500,.17,3.8,M.sidewalk);addBox(city,0,.03,v-7.7,500,.17,3.8,M.sidewalk);addBox(city,v+7.7,.03,0,3.8,.17,500,M.sidewalk);addBox(city,v-7.7,.03,0,3.8,.17,500,M.sidewalk);for(let p=-225;p<=225;p+=10){addBox(city,p,.035,v,4,.015,.11,M.roadLine);addBox(city,v,.035,p,.11,.015,4,M.roadLine);}}
const facades=[M.cream,M.ochre,M.pale,M.blue,M.red,M.green];let seed=12451;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};
function building(x,z,w,d,h,variant){const g=new THREE.Group();city.add(g);addBox(g,x,h/2,z,w,h,d,facades[variant%6]);addBox(g,x,h+.13,z,w+.22,.26,d+.22,M.trim);const floors=Math.max(1,Math.floor(h/3.2)),cols=Math.max(1,Math.floor(w/3.4));for(let f=0;f<floors;f++)for(let c=0;c<cols;c++){const wx=x-w/2+(c+.5)*w/cols,wy=1.15+f*3.1;if(wy>h-.8)continue;addBox(g,wx,wy,z+d/2+.055,1.05,1.45,.09,M.window);addBox(g,wx,wy,z+d/2+.105,1.28,1.7,.07,M.trim);}if(variant%3===0){addBox(g,x,1.05,z+d/2+.1,2.4,2.15,.12,M.blue);addBox(g,x,2.32,z+d/2+.2,3.5,.42,.45,variant%2?M.red:M.green);addBox(g,x,2.34,z+d/2+.44,3.1,.08,.04,M.white);}addBox(g,x,h+.35,z+d/2,w+.35,.62,.22,M.trim);if(rand()>.56)addCylinder(g,x+(rand()-.5)*w,h+.75,z+(rand()-.5)*d,.48,.9,M.dark);}
for(let bx=-4;bx<=4;bx++)for(let bz=-4;bz<=4;bz++){const cx=bx*48,cz=bz*48;if(Math.abs(cx)<30&&Math.abs(cz)<30)continue;const style=Math.floor(rand()*6),count=1+(rand()>.42?1:0);for(let i=0;i<count;i++){const side=i===0?-1:1;building(cx+side*(4+rand()*5),cz+(rand()-.5)*19,7+rand()*5,8+rand()*5,6+rand()*8,style+i);}}
const props=new THREE.Group();city.add(props);
function palm(x,z){addCylinder(props,x,2.3,z,.22,4.6,M.ochre);for(let i=0;i<6;i++){const a=i*Math.PI/3,leaf=addBox(props,x+Math.sin(a)*1.1,4.65,z+Math.cos(a)*1.1,2.3,.13,.36,M.green,a);leaf.rotation.z=Math.cos(a)*-.3;}}
function streetlamp(x,z){addCylinder(props,x,3,z,.07,6,M.dark);addBox(props,x+.75,5.8,z,1.5,.08,.08,M.dark);addSphere(props,x+1.4,5.75,z,.16,.12,.16,M.lamp);}
for(let p=-190;p<=190;p+=48)for(const s of [-1,1]){palm(p+s*9,s*9);streetlamp(p+s*9,s*7);}
const minaret=new THREE.Group();props.add(minaret);minaret.position.set(-20,0,-24);addBox(minaret,0,5,0,5,10,5,M.cream);addBox(minaret,0,10.5,0,5.8,1,5.8,M.trim);addBox(minaret,0,14,0,3.5,6,3.5,M.ochre);addCylinder(minaret,0,19,0,.15,3,M.metal);
const vehicles=[{id:'z750',name:'Kawasaki Z750',type:'MOTORCYCLE',price:0,color:'#d83b36',kind:'bike',max:215,power:1},{id:'retro',name:'Café Racer 650',type:'MOTORCYCLE',price:4200,color:'#d4b674',kind:'bike',max:185,power:.88},{id:'street',name:'Atlas Street 900',type:'MOTORCYCLE',price:7800,color:'#3f807e',kind:'bike',max:230,power:1.08},{id:'compact',name:'City Compact',type:'CAR',price:12500,color:'#d6cdb1',kind:'car',max:170,power:.78},{id:'coupe',name:'Medina Sport',type:'CAR',price:24800,color:'#b4493b',kind:'car',max:245,power:1.12},{id:'suv',name:'Carthage 4×4',type:'CAR',price:33600,color:'#5a7161',kind:'car',max:195,power:.92}];
const stored=(()=>{try{return JSON.parse(localStorage.getItem('tunisMotoSave'))||{};}catch{return {};}})();
const state={money:stored.money??2450,owned:stored.owned||['z750'],active:stored.active||'z750',parts:stored.parts||{},paint:stored.paint||{},time:stored.time||'day',distance:stored.distance||0,gear:0,speed:0,rpm:1.1,clutch:false,toastTimer:0,sound:true,paused:false,pausedDriving:false};
function save(){try{localStorage.setItem('tunisMotoSave',JSON.stringify({money:state.money,owned:state.owned,active:state.active,parts:state.parts,paint:state.paint,time:state.time,distance:state.distance}));}catch{}}

