function save(){try{localStorage.setItem('tunisMotoSave',JSON.stringify({money:state.money,owned:state.owned,active:state.active,parts:state.parts,paint:state.paint,time:state.time,distance:state.distance}));}catch{}}
const vehicleRoot=new THREE.Group();scene.add(vehicleRoot);let vehicleModel,frontWheel,rearWheel,wheels=[],rider;
function makeWheel(parent,z,r=.43){const g=new THREE.Group();g.position.set(0,r,z);parent.add(g);addCylinder(g,0,0,0,r,.22,M.tire,0,Math.PI/2);addCylinder(g,0,0,0,r*.58,.24,M.metal,0,Math.PI/2);addCylinder(g,0,0,0,.1,.27,M.dark,0,Math.PI/2);wheels.push(g);return g;}
function buildBike(v){const root=new THREE.Group(),paint=mat(state.paint[v.id]||v.color,.36,.15),shiny=mat('#b8c0bb',.3,.75);rearWheel=makeWheel(root,-.91,.44);frontWheel=makeWheel(root,1.02,.44);addBox(root,0,.87,-.25,.36,.46,.74,paint);addBox(root,0,1.12,.12,.46,.23,.54,paint);addBox(root,0,1.15,-.82,.38,.2,.48,M.black);addBox(root,0,1.28,-.45,.34,.12,.63,M.black);addBox(root,0,1.3,-.05,.46,.11,.3,M.dark);addCylinder(root,0,.75,-.38,.22,.52,shiny,Math.PI/2);addBox(root,.22,.75,-.35,.17,.43,M.metal);for(const x of [-.15,.15]){const fork=addCylinder(root,x,.81,.94,.045,.94,shiny);fork.rotation.x=.14;}addBox(root,0,1.54,1.13,.77,.07,.07,shiny);addCylinder(root,0,1.52,1.22,.13,.2,M.white,Math.PI/2);for(const x of [-.34,.34]){addCylinder(root,x,1.75,.12,.025,.5,M.metal);addBox(root,x,2,.12,.27,.15,.08,M.dark);}addCylinder(root,.28,.7,-.7,.105,.83,mat('#8b918c',.32,.8),Math.PI/2);rider=new THREE.Group();root.add(rider);addSphere(rider,0,1.8,-.25,.25,.31,.25,mat('#d7b697'));addBox(rider,0,1.43,-.24,.5,.66,.42,mat('#202d2c'),-.12);addBox(rider,-.19,1.02,-.48,.18,.55,.18,M.black,.22);addBox(rider,.19,1.02,-.48,.18,.55,.18,M.black,-.22);return root;}
function buildCar(v){const root=new THREE.Group(),paint=mat(state.paint[v.id]||v.color,.34,.16),windowM=mat('#536d70',.24,.15),chrome=mat('#aeb6af',.3,.7);addBox(root,0,.7,-.08,1.9,.75,3.8,paint);addBox(root,0,1.22,-.13,1.62,.65,2.1,paint);addBox(root,0,1.24,.03,1.54,.48,1.12,windowM);addBox(root,0,1.22,-.85,1.48,.45,.86,windowM);addBox(root,0,.43,1.85,1.76,.3,.12,chrome);addBox(root,0,.44,-1.98,1.75,.28,.12,M.dark);for(const x of [-.97,.97])for(const z of [-1.25,1.28]){const wheel=makeWheel(root,z,.37);wheel.position.set(x,.38,z);}for(const x of [-.65,.65]){addBox(root,x,.81,1.94,.42,.18,.06,M.white);addBox(root,x,.7,-2.04,.38,.16,.06,M.red);}addBox(root,0,1.62,-.6,1.75,.08,.28,M.dark);return root;}
function currentVehicle(){return vehicles.find(v=>v.id===state.active)||vehicles[0];}
function refreshVehicle(){if(vehicleModel)vehicleRoot.remove(vehicleModel);wheels=[];const v=currentVehicle();vehicleModel=v.kind==='bike'?buildBike(v):buildCar(v);vehicleRoot.add(vehicleModel);vehicleRoot.position.set(0,.15,4);vehicleRoot.rotation.set(0,0,0);state.gear=0;state.speed=0;state.rpm=1.1;$('#vehicle-name').textContent=v.name.toUpperCase();$('#vehicle-name').parentElement.parentElement.querySelector('.vehicle-icon').textContent=v.kind==='bike'?'◈':'▰';$('#gear-display').textContent='N';save();}
refreshVehicle();
function setNight(night){state.time=night?'night':'day';document.body.classList.toggle('night',night);$('#time-label').textContent=night?'NIGHT RIDE':'DAYTIME';if(night){scene.background.set('#172234');scene.fog.color.set('#172234');hemi.intensity=.62;sun.intensity=.35;sun.color.set('#a4b9ef');}else{scene.background.copy(daySky);scene.fog.color.copy(daySky);hemi.intensity=2.15;sun.intensity=2.15;sun.color.set('#fff0ce');}save();}setNight(state.time==='night');
function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.setSize(innerWidth,innerHeight);}addEventListener('resize',resize,{passive:true});
function showToast(message){const toast=$('#toast');toast.textContent=message;toast.classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>toast.classList.remove('show'),2100);}
function setGear(dir){if(!state.clutch){showToast('Hold the clutch to shift gears');return;}state.gear=THREE.MathUtils.clamp(state.gear+dir,0,6);$('#gear-display').textContent=state.gear===0?'N':state.gear;showToast(state.gear===0?'Neutral gear':`Gear ${state.gear}`);}
const controls={left:false,right:false,accelerate:false,brake:false,front:false,rear:false,clutch:false,wheelie:false};
function down(key){if(key==='up'){setGear(1);return;}if(key==='down'){setGear(-1);return;}if(key in controls){controls[key]=true;if(key==='clutch'){state.clutch=true;$('#gear-display').classList.add('clutch-on');}}}
function up(key){if(key in controls){controls[key]=false;if(key==='clutch'){state.clutch=false;$('#gear-display').classList.remove('clutch-on');}}}
document.querySelectorAll('[data-control]').forEach(btn=>{const key=btn.dataset.control;btn.addEventListener('pointerdown',e=>{e.preventDefault();btn.setPointerCapture?.(e.pointerId);btn.classList.add('active');down(key);});const release=()=>{btn.classList.remove('active');up(key);};btn.addEventListener('pointerup',release);btn.addEventListener('pointercancel',release);btn.addEventListener('lostpointercapture',release);});
const keys={ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right',ArrowUp:'accelerate',KeyW:'accelerate',Space:'brake',KeyS:'brake',KeyF:'front',KeyB:'rear',KeyC:'clutch',KeyQ:'down',KeyE:'up',ShiftLeft:'up',ControlLeft:'down',KeyR:'wheelie'};addEventListener('keydown',e=>{if(keys[e.code]){e.preventDefault();if(!e.repeat)down(keys[e.code]);}if(e.code==='Escape')togglePause();});addEventListener('keyup',e=>{if(keys[e.code])up(keys[e.code]);});
let audioCtx,osc,engineGain,filter;function startEngineAudio(){if(!state.sound)return;try{audioCtx||=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();if(osc)return;osc=audioCtx.createOscillator();filter=audioCtx.createBiquadFilter();engineGain=audioCtx.createGain();osc.type='sawtooth';filter.type='lowpass';engineGain.gain.value=.0001;osc.connect(filter).connect(engineGain).connect(audioCtx.destination);osc.start();}catch{}}function updateAudio(){if(!osc||!audioCtx)return;osc.frequency.setTargetAtTime(38+state.rpm*28+(state.gear>0?state.gear*3:0),audioCtx.currentTime,.08);filter.frequency.setTargetAtTime(220+state.rpm*180,audioCtx.currentTime,.1);engineGain.gain.setTargetAtTime(state.sound?.025:0,audioCtx.currentTime,.12);}document.addEventListener('pointerdown',startEngineAudio,{once:true});
$('#sound-toggle').addEventListener('click',()=>{state.sound=!state.sound;$('#sound-toggle').textContent=state.sound?'♫':'♪';startEngineAudio();showToast(state.sound?'Engine sound on':'Engine sound off');});$('#cycle-btn').addEventListener('click',()=>setNight(state.time!=='night'));
function togglePause(){state.paused=!state.paused;$('#paused').classList.toggle('hidden',!state.paused);}$('#pause-btn').addEventListener('click',togglePause);$('#resume-btn').addEventListener('click',togglePause);

