const overlay=$('#overlay');let activePanel='garage',tuningTab=0;
function showPanel(name){state.pausedDriving=true;activePanel=name;const copy={garage:['YOUR COLLECTION','Garage','Pick a vehicle. Installed parts stay in your inventory.'],dealer:['TUNIS AUTO MALL','Dealership','Take home a new ride and explore the city.'],tuning:['WORKSHOP · PARTS & PAINT','Tuning garage','Buy upgrades, fit them to your ride, and make it yours.']}[name];$('#panel-eyebrow').textContent=copy[0];$('#panel-title').textContent=copy[1];$('#panel-desc').textContent=copy[2];renderPanel();overlay.classList.remove('hidden');}
function closePanel(){overlay.classList.add('hidden');state.pausedDriving=false;}
document.querySelectorAll('.quick-menu [data-panel]').forEach(b=>b.addEventListener('click',()=>showPanel(b.dataset.panel)));$('#close-panel').addEventListener('click',closePanel);overlay.addEventListener('click',e=>{if(e.target===overlay)closePanel();});
const partList=[{id:'engine',name:'Stage 1 engine tune',detail:'Sharper response · +8% power',price:850,icon:'◉'},{id:'exhaust',name:'Performance exhaust',detail:'Lightweight alloy · deeper tone',price:980,icon:'≋'},{id:'wheels',name:'Forged alloy wheels',detail:'Lightweight street setup',price:720,icon:'◌'},{id:'tires',name:'Performance tires',detail:'Extra grip in the corners',price:530,icon:'◉'},{id:'suspension',name:'Sport suspension',detail:'Lower stance · firmer handling',price:680,icon:'↕'},{id:'brakes',name:'Performance brake kit',detail:'Improved stopping power',price:910,icon:'⊕'},{id:'lights',name:'LED headlight kit',detail:'Bright warm-white beam',price:390,icon:'✧'},{id:'turbo',name:'Turbocharger kit',detail:'Extra boost for the boulevard',price:1850,icon:'↗'},{id:'spoiler',name:'Street spoiler',detail:'Subtle rear aero',price:640,icon:'⌁'},{id:'stickers',name:'Medina sticker pack',detail:'Local artist vinyl set',price:160,icon:'✳'}];
function updateWallet(){$('#money').textContent=state.money.toLocaleString();}updateWallet();
function setPart(id,installed){const all=state.parts[state.active]||[];let item=all.find(p=>p.id===id);if(!item){item={id,installed:false};all.push(item);}item.installed=installed;state.parts[state.active]=all;save();}
function cardButton(text,disabled=false){return `<button class="card-button" ${disabled?'disabled':''}>${text}</button>`;}
function renderPanel(){const content=$('#panel-content');content.innerHTML='';const v=currentVehicle();if(activePanel==='garage'){vehicles.filter(item=>state.owned.includes(item.id)).forEach(item=>{const card=document.createElement('article');card.className='vehicle-card';const count=(state.parts[item.id]||[]).filter(p=>p.installed).length;card.innerHTML=`<div><div class="card-top"><span class="card-type">${item.type} · ${item.id===state.active?'ACTIVE RIDE':'OWNED'}</span><span class="card-icon">${item.kind==='bike'?'◈':'▰'}</span></div><h3>${item.name}</h3><p>${item.max} km/h top speed · ${count} fitted parts</p></div><div class="card-footer"><span class="card-price">${item.id===state.active?'OUT RIDING':'IN GARAGE'}</span>${cardButton(item.id===state.active?'SELECTED':'TAKE RIDE',item.id===state.active)}</div>`;card.querySelector('button').onclick=()=>{state.active=item.id;refreshVehicle();showToast(`${item.name} ready to ride`);renderPanel();};content.append(card);});}
if(activePanel==='dealer'){vehicles.forEach(item=>{const owned=state.owned.includes(item.id),card=document.createElement('article');card.className='vehicle-card';card.innerHTML=`<div><div class="card-top"><span class="card-type">${item.type} · ${item.max} KM/H</span><span class="card-icon">${item.kind==='bike'?'◈':'▰'}</span></div><h3>${item.name}</h3><p>${item.kind==='bike'?'Six-speed manual · street bike':'Manual gearbox · city ready'}</p></div><div class="card-footer"><span class="card-price">${owned?'OWNED':item.price.toLocaleString()+' DT'}</span>${cardButton(owned?(state.active===item.id?'ACTIVE':'SELECT'):'BUY RIDE',!owned&&state.money<item.price)}</div>`;card.querySelector('button').onclick=()=>{if(owned){state.active=item.id;refreshVehicle();showToast(`${item.name} ready to ride`);}else if(state.money>=item.price){state.money-=item.price;state.owned.push(item.id);state.active=item.id;refreshVehicle();updateWallet();showToast('New ride added to your garage');}save();renderPanel();};content.append(card);});}
if(activePanel==='tuning'){const tools=document.createElement('div');tools.className='tuning-tools';tools.style.gridColumn='1/-1';tools.innerHTML=`<button class="${tuningTab===0?'selected':''}">${v.kind==='bike'?'MOTORCYCLE':'CAR'} PARTS</button><button class="${tuningTab===1?'selected':''}">PAINT</button><button class="${tuningTab===2?'selected':''}">SOUND</button>`;content.append(tools);tools.querySelectorAll('button').forEach((b,i)=>b.onclick=()=>{tuningTab=i;renderPanel();});if(tuningTab===1){const card=document.createElement('article');card.className='upgrade-card paint-card';card.style.gridColumn='1/-1';card.innerHTML=`<div><span class="card-type">BODYWORK</span><h3>Choose your paint</h3><p>Color is saved to this vehicle in your garage.</p></div><div class="card-footer"><input class="color-input" type="color" value="${state.paint[v.id]||v.color}" aria-label="Choose paint color">${cardButton('APPLY PAINT · 120 DT')}</div>`;card.querySelector('button').onclick=()=>{if(state.money<120){showToast('Not enough dinars');return;}state.money-=120;state.paint[v.id]=card.querySelector('input').value;updateWallet();refreshVehicle();save();showToast('Fresh paint applied');};content.append(card);}else if(tuningTab===2){const card=document.createElement('article');card.className='upgrade-card';card.style.gridColumn='1/-1';card.innerHTML=`<div><span class="card-type">ENGINE NOTE</span><h3>Sound profile</h3><p>${state.sound?'Engine audio is enabled':'Engine audio is muted'}. Start the engine with any touch.</p></div><div class="card-footer"><span class="card-price">OFFLINE AUDIO</span>${cardButton(state.sound?'MUTE':'ENABLE SOUND')}</div>`;card.querySelector('button').onclick=()=>{$('#sound-toggle').click();renderPanel();};content.append(card);}else{partList.filter(p=>v.kind==='bike'?p.id!=='turbo'&&p.id!=='spoiler':!['exhaust','lights'].includes(p.id)).forEach(p=>{const old=(state.parts[v.id]||[]).find(q=>q.id===p.id),installed=old?.installed||false,card=document.createElement('article');card.className='upgrade-card';card.innerHTML=`<div><div class="card-top"><span class="card-type">${old?(installed?'INSTALLED':'IN INVENTORY'):'UPGRADE'}</span><span class="card-icon">${p.icon}</span></div><h3>${p.name}</h3><p>${p.detail}</p></div><div class="card-footer"><span class="card-price">${old?'OWNED':p.price.toLocaleString()+' DT'}</span>${cardButton(old?(installed?'UNINSTALL':'INSTALL'):'BUY & FIT',!old&&state.money<p.price)}</div>`;card.querySelector('button').onclick=()=>{if(old){setPart(p.id,!installed);showToast(installed?'Uninstalled · in your inventory':'Part fitted to your ride');}else if(state.money>=p.price){state.money-=p.price;setPart(p.id,true);updateWallet();showToast('Part bought and fitted');}else showToast('Not enough dinars');refreshVehicle();renderPanel();};content.append(card);});}}}

